"""Practical, plain-language trading lessons for the in-app learning flow."""


def _lesson(
    lesson_id: str,
    tier: int,
    title: str,
    content: str,
    question: str,
    options: tuple[str, str, str],
    answer: int,
    explanation: str,
) -> dict:
    return {
        "id": lesson_id,
        "tier": tier,
        "title": title,
        "content": content,
        "question": question,
        "options": list(options),
        "answer": answer,
        "explanation": explanation,
    }


